template:
% 参数由系统自动注入：\def\ab{5} \def\ac{6} \def\anglea{60} \def\showtriangle{1} \def\showincircle{1} \def\showcenter{1} \def\showradius{0} \def\showtouchpoints{0} \def\showbisectors{0} \def\labela{A} \def\labelb{B} \def\labelc{C} \def\labeli{I} \def\labeld{D} \def\labele{E} \def\labelf{F}
% 视觉归一化：把三角形较长的给定边缩放到 6 个坐标单位（约 6cm），保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{6 / max(\ab, \ac)}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
% 顶点：A 在原点，B 在正 x 轴，C 由 ac 与 ∠A 定位（SAS 给定，恒为合法三角形）
\pgfmathsetmacro{\Cx}{\ac*cos(\anglea)}
\pgfmathsetmacro{\Cy}{\ac*sin(\anglea)}
% 三边：sidea=BC（∠A 的对边），sideb=CA，sidec=AB
\pgfmathsetmacro{\sidea}{sqrt((\Cx-\ab)^2 + \Cy*\Cy)}
\pgfmathsetmacro{\sideb}{\ac}
\pgfmathsetmacro{\sidec}{\ab}
\pgfmathsetmacro{\sper}{\sidea + \sideb + \sidec}
\pgfmathsetmacro{\semi}{\sper/2}
% 内心 I = (a·A + b·B + c·C)/(a+b+c)；内切圆半径 r = 面积 / 半周长
\pgfmathsetmacro{\Ix}{(\sideb*\ab + \sidec*\Cx)/\sper}
\pgfmathsetmacro{\Iy}{(\sidec*\Cy)/\sper}
\pgfmathsetmacro{\tarea}{0.5*\ab*\ac*sin(\anglea)}
\pgfmathsetmacro{\inr}{\tarea/\semi}
% 三边切点：切线长 AE=AF=s-a、BF=BD=s-b、CD=CE=s-c
\pgfmathsetmacro{\Fx}{\semi - \sidea}
\pgfmathsetmacro{\Fy}{0}
\pgfmathsetmacro{\Ex}{(\semi - \sidea)*cos(\anglea)}
\pgfmathsetmacro{\Ey}{(\semi - \sidea)*sin(\anglea)}
\pgfmathsetmacro{\Dx}{\ab + (\semi - \sideb)*(\Cx-\ab)/\sidea}
\pgfmathsetmacro{\Dy}{(\semi - \sideb)*\Cy/\sidea}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\ab,0);
  \coordinate (C) at (\Cx,\Cy);
  \coordinate (I) at (\Ix,\Iy);
  \coordinate (D) at (\Dx,\Dy);
  \coordinate (E) at (\Ex,\Ey);
  \coordinate (F) at (\Fx,\Fy);
  % 三角形 ABC
  \ifnum\showtriangle>0
    \draw[thick] (A) -- (B) -- (C) -- cycle;
  \fi
  % 内切圆
  \ifnum\showincircle>0
    \draw[thick] (I) circle [radius=\inr];
  \fi
  % 三条角平分线（交于内心）：按邻边比例定出在对边上的落点
  \ifnum\showbisectors>0
    \draw[thick] (A) -- ({\ab + \sidec/(\sideb+\sidec)*(\Cx-\ab)},{\sidec/(\sideb+\sidec)*\Cy});
    \draw[thick] (B) -- ({\sidec/(\sidea+\sidec)*\Cx},{\sidec/(\sidea+\sidec)*\Cy});
    \draw[thick] (C) -- ({\sideb/(\sidea+\sideb)*\ab},0);
  \fi
  % 内心到切点的半径 + 直角记号（半径⊥切线）
  \ifnum\showradius>0
    \pgfmathsetmacro{\rmsz}{min(0.2/\figscale, \inr*0.34)}
    \draw[thick] (I) -- (\Fx,\Fy);
    \pgfmathsetmacro{\ufx}{(\Ix - (\Fx))/\inr}
    \pgfmathsetmacro{\ufy}{(\Iy - (\Fy))/\inr}
    \pgfmathsetmacro{\wfx}{1}
    \pgfmathsetmacro{\wfy}{0}
    \draw[thick] ({\Fx+\rmsz*\wfx},{\Fy+\rmsz*\wfy}) -- ({\Fx+\rmsz*\wfx+\rmsz*\ufx},{\Fy+\rmsz*\wfy+\rmsz*\ufy}) -- ({\Fx+\rmsz*\ufx},{\Fy+\rmsz*\ufy});
    \draw[thick] (I) -- (\Ex,\Ey);
    \pgfmathsetmacro{\uex}{(\Ix - (\Ex))/\inr}
    \pgfmathsetmacro{\uey}{(\Iy - (\Ey))/\inr}
    \pgfmathsetmacro{\wex}{-cos(\anglea)}
    \pgfmathsetmacro{\wey}{-sin(\anglea)}
    \draw[thick] ({\Ex+\rmsz*\wex},{\Ey+\rmsz*\wey}) -- ({\Ex+\rmsz*\wex+\rmsz*\uex},{\Ey+\rmsz*\wey+\rmsz*\uey}) -- ({\Ex+\rmsz*\uex},{\Ey+\rmsz*\uey});
    \draw[thick] (I) -- (\Dx,\Dy);
    \pgfmathsetmacro{\udx}{(\Ix - (\Dx))/\inr}
    \pgfmathsetmacro{\udy}{(\Iy - (\Dy))/\inr}
    \pgfmathsetmacro{\wdx}{-(\Cx-\ab)/\sidea}
    \pgfmathsetmacro{\wdy}{-\Cy/\sidea}
    \draw[thick] ({\Dx+\rmsz*\wdx},{\Dy+\rmsz*\wdy}) -- ({\Dx+\rmsz*\wdx+\rmsz*\udx},{\Dy+\rmsz*\wdy+\rmsz*\udy}) -- ({\Dx+\rmsz*\udx},{\Dy+\rmsz*\udy});
  \fi
  % 三个切点及字母
  \ifnum\showtouchpoints>0
    \fill (D) circle [radius=\dotr pt];
    \node[above right=2pt] at (D) {$\labeld$};
    \fill (E) circle [radius=\dotr pt];
    \node[above left=2pt] at (E) {$\labele$};
    \fill (F) circle [radius=\dotr pt];
    \node[below=2pt] at (F) {$\labelf$};
  \fi
  % 内心 I
  \ifnum\showcenter>0
    \fill (I) circle [radius=\dotr pt];
    \node[left=3pt] at (I) {$\labeli$};
  \fi
  % 顶点字母
  \node[below left=2pt] at (A) {$\labela$};
  \node[below right=2pt] at (B) {$\labelb$};
  \node[above=2pt] at (C) {$\labelc$};
\end{tikzpicture}
